import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        new TaskC().solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            if (n >= 100) {
                out.print(0);
                return;
            }

            int[][] points = new int[n + 1][5];
            for (int i = 1; i <= n; i++) {
                points[i][0] = in.nextInt();
                points[i][1] = in.nextInt();
                points[i][2] = in.nextInt();
                points[i][3] = in.nextInt();
                points[i][4] = in.nextInt();
            }

            BitSet bad = new BitSet(n + 1);

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    for (int k = 1; k <= n; k++) {
                        if (i == j || j == k || k == i) {
                            continue;
                        }

                        long[] v1 = new long[5];
                        long[] v2 = new long[5];
                        for (int t = 0; t < 5; t++) {
                            v1[t] = points[j][t] - points[i][t];
                            v2[t] = points[k][t] - points[i][t];
                        }

                        double dot = 0;
                        long norm1Sq = 0;
                        long norm2Sq = 0;
                        for (int t = 0; t < 5; t++) {
                            dot += v1[t] * v2[t];
                            norm1Sq += v1[t] * v1[t];
                            norm2Sq += v2[t] * v2[t];
                        }

                        double val = dot / Math.sqrt(norm1Sq) / Math.sqrt(norm2Sq);
                        if (Math.toDegrees(Math.acos(val)) + 0.000000001 < 90) {
                            bad.set(i);
                        }
                    }
                }
            }

            out.println(n - bad.cardinality());
            for (int i = 1; i <= n; i++) {
                if (!bad.get(i)) {
                    out.println(i);
                }
            }
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
